    if std::ptr::fn_addr_eq(op, vm::op_f64_trunc as Op) {
        return Some(PureOpKind::F64Trunc);
    }
    if std::ptr::fn_addr_eq(op, vm::op_f64_nearest as Op) {
        return Some(PureOpKind::F64Nearest);
    }
    None
