fn maps_to_specialized_memory_family(sources: &[Op], mapper: fn(Op) -> Option<Op>, op: Op) -> bool {
    sources
        .iter()
        .filter_map(|source| mapper(*source))
        .any(|candidate| std::ptr::fn_addr_eq(candidate, op))
}

pub(super) fn specialized_memory_family(op: Op) -> Option<SpecializedMemoryFamily> {
    if maps_to_specialized_memory_family(LOCAL_BASE_MEMORY_SOURCES, specialized_memory_op, op) {
        return Some(SpecializedMemoryFamily::LocalBase);
    }
    if maps_to_specialized_memory_family(
        INDEXED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::IndexedLocalBase);
    }
    if maps_to_specialized_memory_family(
        SHARED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::SharedLocalBase);
    }
    if maps_to_specialized_memory_family(
        INDEXED_SHARED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::IndexedSharedLocalBase);
    }
    if maps_to_specialized_memory_family(
        LOCAL_BASE_MEMORY_SOURCES,
        specialized_scaled_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::LocalScaledIndex);
    }
    if maps_to_specialized_memory_family(
        INDEXED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_scaled_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::IndexedLocalScaledIndex);
    }
    if maps_to_specialized_memory_family(
        SHARED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_scaled_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::SharedLocalScaledIndex);
    }
    if maps_to_specialized_memory_family(
        INDEXED_SHARED_LOCAL_BASE_MEMORY_SOURCES,
        specialized_scaled_memory_op,
        op,
    ) {
        return Some(SpecializedMemoryFamily::IndexedSharedLocalScaledIndex);
    }
    None
}

fn block_op_i32_const(op: &BlockOp) -> Option<i32> {
    matches!(op.kind, BlockOpKind::Const).then(|| match op.operands.first()? {
        BlockOperand::I32(value) => Some(*value),
        _ => None,
    })?
}

fn block_op_scalar_const_operand(op: &BlockOp) -> Option<BlockOperand> {
    if op.kind != BlockOpKind::Const {
        return None;
    }
    match *op.operands.first()? {
        operand @ (BlockOperand::I32(_)
        | BlockOperand::I64(_)
        | BlockOperand::F32(_)
        | BlockOperand::F64(_)) => Some(operand),
        _ => None,
    }
}

fn scalar_const_operand_from_value(value: Option<ConstValue>) -> Option<BlockOperand> {
    match value? {
        ConstValue::I32(value) => Some(BlockOperand::I32(value)),
        ConstValue::I64(value) => Some(BlockOperand::I64(value)),
        ConstValue::F32(value) => Some(BlockOperand::F32(value)),
        ConstValue::F64(value) => Some(BlockOperand::F64(value)),
    }
}

fn scalar_const_operand_size(operand: BlockOperand) -> Option<u32> {
    match operand {
        BlockOperand::I32(_) | BlockOperand::F32(_) => Some(4),
        BlockOperand::I64(_) | BlockOperand::F64(_) => Some(8),
        _ => None,
    }
}

fn scalar_const_operand_op(operand: BlockOperand) -> Option<Op> {
    match operand {
        BlockOperand::I32(_) => Some(vm::op_i32_const as Op),
        BlockOperand::I64(_) => Some(vm::op_i64_const as Op),
        BlockOperand::F32(_) => Some(vm::op_f32_const as Op),
        BlockOperand::F64(_) => Some(vm::op_f64_const as Op),
        _ => None,
    }
}

fn licm_origin_values(graph: &ValueGraph) -> HashMap<ExprOrigin, ValueRef> {
    let mut origin_values = HashMap::new();
    for (expr_idx, node) in graph.nodes.iter().enumerate() {
        origin_values.insert(node.origin, ExprId(expr_idx));
    }
    origin_values
}

fn licm_producer_indices(body: &BlockBody) -> HashMap<ValueRef, usize> {
    let mut out = HashMap::new();
    for (index, op) in body.ops.iter().enumerate() {
        if let Some(value) = block_op_single_result(op) {
            out.insert(value, index);
        }
    }
    out
}

fn block_op_eligible_for_licm(graph: &ValueGraph, op: &BlockOp) -> bool {
    block_op_single_use_for_licm(graph, op)
}

#[allow(clippy::too_many_arguments)]
fn collect_licm_value_ops(
    graph: &ValueGraph,
    body: &BlockBody,
    value: ValueRef,
    producer_indices: &HashMap<ValueRef, usize>,
    origin_values: &HashMap<ExprOrigin, ValueRef>,
    effects: &LoopEffects,
    op_indices: &mut BTreeSet<usize>,
) -> Option<()> {
    let node = &graph[value.0];
    if node.const_value.is_some() || matches!(node.origin.kind, ExprOriginKind::EntryLocal) {
        let &index = producer_indices.get(&value)?;
        let op = body.ops.get(index)?;
        if let Some(slot) = block_op_local_get_slot(op) {
            if effects.local_writes.contains(&slot) || !block_op_eligible_for_licm(graph, op) {
                return None;
            }
        } else if !matches!(op.kind, BlockOpKind::Const) || !block_op_eligible_for_licm(graph, op) {
            return None;
        }
        op_indices.insert(index);
        return Some(());
    }
    if node.is_block_argument() {
        return None;
    }
    if node.is_effect_result() {
        let &index = producer_indices.get(&value)?;
        let op = body.ops.get(index)?;
        let slot = block_op_global_get_slot(op)?;
        if effects.global_writes.contains(&slot)
            || effects.has_call_barrier
            || !block_op_eligible_for_licm(graph, op)
        {
            return None;
        }
        op_indices.insert(index);
        return Some(());
    }
    let &index = producer_indices.get(&value)?;
    let op = body.ops.get(index)?;
    if !matches!(
        op.kind,
        BlockOpKind::PureUnary(_) | BlockOpKind::PureBinary(_)
    ) || !block_op_eligible_for_licm(graph, op)
    {
        return None;
    }
    match node.key? {
        ValueKey::Unary { input, .. } => {
            let input = origin_values.get(&input).copied()?;
            collect_licm_value_ops(
                graph,
                body,
                input,
                producer_indices,
                origin_values,
                effects,
                op_indices,
            )?;
        }
        ValueKey::Binary { lhs, rhs, .. } => {
            let lhs = origin_values.get(&lhs).copied()?;
            let rhs = origin_values.get(&rhs).copied()?;
            collect_licm_value_ops(
                graph,
                body,
                lhs,
                producer_indices,
                origin_values,
                effects,
                op_indices,
            )?;
            collect_licm_value_ops(
                graph,
                body,
                rhs,
                producer_indices,
                origin_values,
                effects,
                op_indices,
            )?;
        }
    }
    op_indices.insert(index);
    Some(())
}

#[allow(dead_code)]
#[derive(Clone, Copy)]
struct MemoryAccess {
    memidx: u32,
    offset: u32,
    width: u8,
    ty: ValType,
}

#[cold]
#[inline(never)]
fn build_specialized_local_root_lowering(
    graph: &ValueGraph,
    body: &BlockBody,
    op_idx: usize,
    op: &BlockOp,
) -> Option<SpecializedLocalControlLowering> {
    if next_entry_is_barrier(body, op_idx + 1) {
        return None;
    }
    if let Some((matched, _root_value, provider_idx)) =
        match_unary_selector_root_shape(graph, body, op_idx, op_idx + 1)
    {
        let absorbed_ops = provider_idx.into_iter().collect();
        let source_start = provider_idx
            .and_then(|idx| body.ops.get(idx))
            .and_then(|provider| provider.source_start)
            .or(op.source_start);
        return Some(SpecializedLocalControlLowering {
            source_start,
            op: matched.kind.root_op(),
            operands: unary_root_operands(matched),
            absorbed_ops,
            consumer_after_idx: op_idx + 1,
        });
    }
    let start_idx = op_idx.checked_sub(2)?;
    if body.ops[start_idx..start_idx + 2]
        .iter()
        .any(|provider| local_get_reads_block_argument(graph, provider))
    {
        return None;
    }
    let (specialized_op, operands) = if let Some((matched, _)) =
        match_numeric_selector_root_shape(graph, body, start_idx, op_idx + 1)
    {
        (numeric_root_opcode(matched), numeric_root_operands(matched))
    } else {
        let (matched, _) = match_selector_root_shape(graph, body, start_idx, op_idx + 1)?;
        match matched {
            SelectorRootMatch::LocalConstAdd { base, imm } => (
                vm::op_local_get4_i32_const_add as Op,
                vec![base, BlockOperand::I32(imm)],
            ),
            SelectorRootMatch::LocalLocalAdd { lhs, rhs } => {
                (vm::op_local_get4_local_get4_i32_add as Op, vec![lhs, rhs])
            }
        }
    };
    Some(SpecializedLocalControlLowering {
        source_start: body
            .ops
            .get(start_idx)
            .and_then(|provider| provider.source_start)
            .or(op.source_start),
        op: specialized_op,
        operands,
        absorbed_ops: absorbed_ops_range(start_idx, op_idx),
        consumer_after_idx: op_idx + 1,
    })
}

#[cold]
#[inline(never)]
fn build_specialized_local_set_tee_lowering(
    graph: &ValueGraph,
    body: &BlockBody,
    op_idx: usize,
    op: &BlockOp,
) -> Option<SpecializedLocalControlLowering> {
    if !matches!(op.kind, BlockOpKind::LocalSet | BlockOpKind::LocalTee) {
        return None;
    }
    if body
        .ops
        .get(op_idx + 1)
        .is_some_and(|_| next_entry_is_barrier(body, op_idx + 1))
    {
        return None;
    }
    let input = *op.inputs.first()?;
    if let Some(spec) =
        build_specialized_const_base_i32_load_add_set_lowering(graph, body, op_idx, op, input)
    {
        return Some(spec);
    }
    if let Some(root_idx) = op_idx.checked_sub(1) {
        if let Some((matched, root_value, provider_idx)) =
            match_unary_selector_root_shape(graph, body, root_idx, op_idx + 1)
        {
            if root_value == input && !value_used_after(body, op_idx + 1, root_value) {
                let dst = *op.operands.first()?;
                let mut operands = unary_root_operands(matched);
                operands.push(dst);
                let mut absorbed_ops = BTreeSet::from([root_idx]);
                if let Some(provider_idx) = provider_idx {
                    absorbed_ops.insert(provider_idx);
                }
                let source_start = provider_idx
                    .and_then(|idx| body.ops.get(idx))
                    .and_then(|provider| provider.source_start)
                    .or_else(|| body.ops.get(root_idx).and_then(|root| root.source_start))
                    .or(op.source_start);
                return Some(SpecializedLocalControlLowering {
                    source_start,
                    op: match op.kind {
                        BlockOpKind::LocalSet => matched.kind.set_op(),
                        BlockOpKind::LocalTee => matched.kind.tee_op(),
                        _ => unreachable!("checked above"),
                    },
                    operands,
                    absorbed_ops,
                    consumer_after_idx: op_idx + 1,
                });
            }
        }
    }
    let start_idx = op_idx.checked_sub(3)?;
    if body.ops[start_idx..start_idx + 2]
        .iter()
        .any(|provider| local_get_reads_block_argument(graph, provider))
    {
        return None;
    }
    let root_op = &body.ops[start_idx + 2];
    if let Some((matched, root_value)) =
        match_numeric_selector_root_shape(graph, body, start_idx, op_idx + 1)
    {
        if root_value == input && !value_used_after(body, op_idx + 1, root_value) {
            let dst = *op.operands.first()?;
            let specialized_op = numeric_set_tee_opcode(matched.kind, op.kind)?;
            let mut operands = numeric_root_operands(matched);
            operands.push(dst);
            return Some(SpecializedLocalControlLowering {
                source_start: body
                    .ops
                    .get(start_idx)
                    .and_then(|provider| provider.source_start)
                    .or(op.source_start),
                op: specialized_op,
                operands,
                absorbed_ops: absorbed_ops_range(start_idx, op_idx),
                consumer_after_idx: op_idx + 1,
            });
        }
    }
    let matched = match_selector_root_shape(graph, body, start_idx, op_idx + 1)
        .and_then(|(matched, root_value)| {
            (root_value == input && !value_used_after(body, op_idx + 1, root_value))
                .then_some(matched)
        })
        .or_else(|| {
            let root_value = block_op_single_result(root_op)?;
            (root_value == input
                && selector_value_is_single_use(graph, root_op, root_value)
                && !value_used_after(body, op_idx + 1, root_value)
                && !value_feeds_memory_address(body, op_idx + 1, root_value))
            .then(|| {
                match_selector_root_shape_from_body(
                    graph,
                    root_op,
                    &body.ops[start_idx],
                    &body.ops[start_idx + 1],
                )
            })
            .flatten()
        })?;
    let dst = *op.operands.first()?;
    let (specialized_op, operands) = match (op.kind, matched) {
        (BlockOpKind::LocalSet, SelectorRootMatch::LocalConstAdd { base, imm }) => (
            vm::op_local_get4_i32_const_add_set4 as Op,
            vec![base, BlockOperand::I32(imm), dst],
        ),
        (BlockOpKind::LocalSet, SelectorRootMatch::LocalLocalAdd { lhs, rhs }) => (
            vm::op_local_get4_local_get4_i32_add_set4 as Op,
            vec![lhs, rhs, dst],
        ),
        (BlockOpKind::LocalTee, SelectorRootMatch::LocalConstAdd { base, imm }) => (
            vm::op_local_get4_i32_const_add_tee4 as Op,
            vec![base, BlockOperand::I32(imm), dst],
        ),
        (BlockOpKind::LocalTee, SelectorRootMatch::LocalLocalAdd { lhs, rhs }) => (
            vm::op_local_get4_local_get4_i32_add_tee4 as Op,
            vec![lhs, rhs, dst],
        ),
        _ => return None,
    };
    Some(SpecializedLocalControlLowering {
        source_start: body
            .ops
            .get(start_idx)
            .and_then(|provider| provider.source_start)
            .or(op.source_start),
        op: specialized_op,
        operands,
        absorbed_ops: absorbed_ops_range(start_idx, op_idx),
        consumer_after_idx: op_idx + 1,
    })
}

fn build_specialized_const_base_i32_load_add_set_lowering(
    graph: &ValueGraph,
    body: &BlockBody,
    op_idx: usize,
    op: &BlockOp,
    input: ValueRef,
) -> Option<SpecializedLocalControlLowering> {
    if op.kind != BlockOpKind::LocalSet {
        return None;
    }
    let root_idx = producer_op_index_before(body, input, op_idx)?;
    let root_op = body.ops.get(root_idx)?;
    if root_op.kind != BlockOpKind::PureBinary(PureOpKind::I32Add)
        || !block_op_single_use(graph, root_op)
        || block_op_single_result(root_op)? != input
        || value_used_after(body, op_idx + 1, input)
    {
        return None;
    }
    let lhs = *root_op.inputs.first()?;
    let rhs = *root_op.inputs.get(1)?;
    let (memarg, memory_absorbed, local_operand, local_provider_idx) =
        if let Some((memarg, absorbed)) = match_const_base_i32_load_input(body, lhs, root_idx) {
            let (local_operand, local_provider_idx) =
                selector_local_get4_operand_for_value(graph, body, rhs, root_idx)?;
            (memarg, absorbed, local_operand, local_provider_idx)
        } else {
            let (memarg, absorbed) = match_const_base_i32_load_input(body, rhs, root_idx)?;
            let (local_operand, local_provider_idx) =
                selector_local_get4_operand_for_value(graph, body, lhs, root_idx)?;
            (memarg, absorbed, local_operand, local_provider_idx)
        };
    let dst = *op.operands.first()?;
    let source_start = memory_absorbed
        .iter()
        .chain(std::iter::once(&local_provider_idx))
        .filter_map(|idx| body.ops.get(*idx))
        .filter_map(|provider| provider.source_start)
        .min()
        .or(root_op.source_start)
        .or(op.source_start);
    let mut absorbed_ops = memory_absorbed;
    absorbed_ops.insert(local_provider_idx);
    absorbed_ops.insert(root_idx);
    Some(SpecializedLocalControlLowering {
        source_start,
        op: vm::op_i32_load_const_base_local_get4_i32_add_set4 as Op,
        operands: vec![BlockOperand::Raw(Operand { memarg }), local_operand, dst],
        absorbed_ops,
        consumer_after_idx: op_idx + 1,
    })
}

fn match_const_base_i32_load_input(
    body: &BlockBody,
    value: ValueRef,
    consumer_idx: usize,
) -> Option<(crate::common::MemArg, BTreeSet<usize>)> {
    let load_idx = producer_op_index_before(body, value, consumer_idx)?;
    let load_op = body.ops.get(load_idx)?;
    if !std::ptr::fn_addr_eq(load_op.op, vm::op_i32_load as Op) {
        return None;
    }
    let address = memory_address_input(load_op)?;
    let (memarg, address_provider_idx) =
        folded_const_base_memarg(body, load_idx, load_op, address)?;
    Some((memarg, BTreeSet::from([address_provider_idx, load_idx])))
}

#[cold]
#[inline(never)]
fn build_specialized_br_if_lowering(
    graph: &ValueGraph,
    body: &BlockBody,
    terminator: &BlockTerminator,
) -> Option<SpecializedLocalControlLowering> {
    if terminator.kind != BlockTerminatorKind::BrIf {
        return None;
    }
    let (fused, consumed) = match_br_if_pattern(graph, body, terminator)?;
    let start_idx = body.ops.len().checked_sub(consumed)?;
    Some(SpecializedLocalControlLowering {
        source_start: body
            .ops
            .get(start_idx)
            .and_then(|provider| provider.source_start)
            .or(terminator.source_start),
        op: fused.op,
        operands: fused.operands,
        absorbed_ops: absorbed_ops_range(start_idx, body.ops.len()),
        consumer_after_idx: body.ops.len(),
    })
}

#[cold]
#[inline(never)]
fn absorbed_ops_range(start_idx: usize, end_exclusive: usize) -> BTreeSet<usize> {
    (start_idx..end_exclusive).collect()
}

fn numeric_rhs_shape(rhs: BlockOperand) -> LocalFastRhsShape {
    match rhs {
        BlockOperand::LocalAddr(_) | BlockOperand::SpillValue(_) => LocalFastRhsShape::Local,
        BlockOperand::I32(_)
        | BlockOperand::I64(_)
        | BlockOperand::F32(_)
        | BlockOperand::F64(_) => LocalFastRhsShape::Const,
        _ => unreachable!("unsupported numeric rhs operand"),
    }
}

fn numeric_root_operands(matched: NumericSelectorRootMatch) -> Vec<BlockOperand> {
    vec![
        BlockOperand::U32(matched.kind.encode_kind(numeric_rhs_shape(matched.rhs))),
        matched.lhs,
        matched.rhs,
    ]
}

fn numeric_root_opcode(matched: NumericSelectorRootMatch) -> Op {
    matched.kind.root_op()
}

fn numeric_set_tee_opcode(kind: NumericSelectorRootKind, op_kind: BlockOpKind) -> Option<Op> {
    match op_kind {
        BlockOpKind::LocalSet => Some(kind.set_op()),
        BlockOpKind::LocalTee => Some(kind.tee_op()),
        _ => None,
    }
}

fn unary_root_operands(matched: UnarySelectorRootMatch) -> Vec<BlockOperand> {
    vec![BlockOperand::U32(matched.kind.encode_kind()), matched.src]
}

#[derive(Clone, Copy)]
enum UnarySelectorRootKind {
    Unary32(LocalUnary32Op),
    Unary64(LocalUnary64Op),
}

impl UnarySelectorRootKind {
    fn from_pure_op(op: PureOpKind) -> Option<Self> {
        Some(match op {
            PureOpKind::I32Clz => Self::Unary32(LocalUnary32Op::I32Clz),
            PureOpKind::I32Ctz => Self::Unary32(LocalUnary32Op::I32Ctz),
            PureOpKind::I32Popcnt => Self::Unary32(LocalUnary32Op::I32Popcnt),
            PureOpKind::I64Clz => Self::Unary64(LocalUnary64Op::I64Clz),
            PureOpKind::I64Ctz => Self::Unary64(LocalUnary64Op::I64Ctz),
            PureOpKind::I64Popcnt => Self::Unary64(LocalUnary64Op::I64Popcnt),
            PureOpKind::F32Abs => Self::Unary32(LocalUnary32Op::F32Abs),
            PureOpKind::F32Neg => Self::Unary32(LocalUnary32Op::F32Neg),
            PureOpKind::F32Sqrt => Self::Unary32(LocalUnary32Op::F32Sqrt),
            PureOpKind::F32Ceil => Self::Unary32(LocalUnary32Op::F32Ceil),
            PureOpKind::F32Floor => Self::Unary32(LocalUnary32Op::F32Floor),
            PureOpKind::F32Trunc => Self::Unary32(LocalUnary32Op::F32Trunc),
            PureOpKind::F32Nearest => Self::Unary32(LocalUnary32Op::F32Nearest),
            PureOpKind::F64Abs => Self::Unary64(LocalUnary64Op::F64Abs),
            PureOpKind::F64Neg => Self::Unary64(LocalUnary64Op::F64Neg),
            PureOpKind::F64Sqrt => Self::Unary64(LocalUnary64Op::F64Sqrt),
            PureOpKind::F64Ceil => Self::Unary64(LocalUnary64Op::F64Ceil),
            PureOpKind::F64Floor => Self::Unary64(LocalUnary64Op::F64Floor),
            PureOpKind::F64Trunc => Self::Unary64(LocalUnary64Op::F64Trunc),
            PureOpKind::F64Nearest => Self::Unary64(LocalUnary64Op::F64Nearest),
            _ => return None,
        })
    }

    const fn input_size(self) -> u32 {
        match self {
            Self::Unary32(_) => 4,
            Self::Unary64(_) => 8,
        }
    }

    fn encode_kind(self) -> u32 {
        match self {
            Self::Unary32(op) => encode_local_unary32_kind(op),
            Self::Unary64(op) => encode_local_unary64_kind(op),
        }
    }

    const fn root_op(self) -> Op {
        match self {
            Self::Unary32(_) => vm::op_local_unary32 as Op,
            Self::Unary64(_) => vm::op_local_unary64 as Op,
        }
    }

    const fn set_op(self) -> Op {
        match self {
            Self::Unary32(_) => vm::op_local_unary32_set4 as Op,
            Self::Unary64(_) => vm::op_local_unary64_set8 as Op,
        }
    }

    const fn tee_op(self) -> Op {
        match self {
            Self::Unary32(_) => vm::op_local_unary32_tee4 as Op,
            Self::Unary64(_) => vm::op_local_unary64_tee8 as Op,
        }
    }
}

#[derive(Clone, Copy)]
struct UnarySelectorRootMatch {
    kind: UnarySelectorRootKind,
    src: BlockOperand,
}

#[derive(Clone, Copy)]
enum SelectorRootMatch {
    LocalConstAdd {
        base: BlockOperand,
        imm: i32,
    },
    LocalLocalAdd {
        lhs: BlockOperand,
        rhs: BlockOperand,
    },
}

#[derive(Clone, Copy)]
enum SelectorCompareMatch {
    Eqz {
        input: BlockOperand,
    },
    Const {
        lhs: BlockOperand,
        cmp_kind: u32,
        imm: i32,
    },
    Local {
        lhs: BlockOperand,
        rhs: BlockOperand,
        cmp_kind: u32,
    },
}

#[derive(Clone, Copy)]
enum NumericSelectorRootKind {
    Binop32(LocalBinop32Op),
    Binop64(LocalBinop64Op),
    Cmp32(LocalCmp32Op),
    Cmp64(LocalCmp64Op),
}

impl NumericSelectorRootKind {
    fn from_pure_op(op: PureOpKind) -> Option<Self> {
        Some(match op {
            PureOpKind::I32Add => Self::Binop32(LocalBinop32Op::I32Add),
            PureOpKind::I32Sub => Self::Binop32(LocalBinop32Op::I32Sub),
            PureOpKind::I32Mul => Self::Binop32(LocalBinop32Op::I32Mul),
            PureOpKind::I32And => Self::Binop32(LocalBinop32Op::I32And),
            PureOpKind::I32Or => Self::Binop32(LocalBinop32Op::I32Or),
            PureOpKind::I32Xor => Self::Binop32(LocalBinop32Op::I32Xor),
            PureOpKind::I32Shl => Self::Binop32(LocalBinop32Op::I32Shl),
            PureOpKind::I32ShrS => Self::Binop32(LocalBinop32Op::I32ShrS),
            PureOpKind::I32ShrU => Self::Binop32(LocalBinop32Op::I32ShrU),
            PureOpKind::I32Rotl => Self::Binop32(LocalBinop32Op::I32Rotl),
            PureOpKind::I32Rotr => Self::Binop32(LocalBinop32Op::I32Rotr),
            PureOpKind::I64Add => Self::Binop64(LocalBinop64Op::I64Add),
            PureOpKind::I64Sub => Self::Binop64(LocalBinop64Op::I64Sub),
            PureOpKind::I64Mul => Self::Binop64(LocalBinop64Op::I64Mul),
            PureOpKind::I64And => Self::Binop64(LocalBinop64Op::I64And),
            PureOpKind::I64Or => Self::Binop64(LocalBinop64Op::I64Or),
            PureOpKind::I64Xor => Self::Binop64(LocalBinop64Op::I64Xor),
            PureOpKind::I64Shl => Self::Binop64(LocalBinop64Op::I64Shl),
            PureOpKind::I64ShrS => Self::Binop64(LocalBinop64Op::I64ShrS),
            PureOpKind::I64ShrU => Self::Binop64(LocalBinop64Op::I64ShrU),
            PureOpKind::I64Rotl => Self::Binop64(LocalBinop64Op::I64Rotl),
            PureOpKind::I64Rotr => Self::Binop64(LocalBinop64Op::I64Rotr),
            PureOpKind::F32Add => Self::Binop32(LocalBinop32Op::F32Add),
            PureOpKind::F32Sub => Self::Binop32(LocalBinop32Op::F32Sub),
            PureOpKind::F32Mul => Self::Binop32(LocalBinop32Op::F32Mul),
            PureOpKind::F32Div => Self::Binop32(LocalBinop32Op::F32Div),
            PureOpKind::F64Add => Self::Binop64(LocalBinop64Op::F64Add),
            PureOpKind::F64Sub => Self::Binop64(LocalBinop64Op::F64Sub),
            PureOpKind::F64Mul => Self::Binop64(LocalBinop64Op::F64Mul),
            PureOpKind::F64Div => Self::Binop64(LocalBinop64Op::F64Div),
            PureOpKind::I32Eq => Self::Cmp32(LocalCmp32Op::I32Eq),
            PureOpKind::I32Ne => Self::Cmp32(LocalCmp32Op::I32Ne),
            PureOpKind::I32LtS => Self::Cmp32(LocalCmp32Op::I32LtS),
            PureOpKind::I32LtU => Self::Cmp32(LocalCmp32Op::I32LtU),
            PureOpKind::I32GtS => Self::Cmp32(LocalCmp32Op::I32GtS),
            PureOpKind::I32GtU => Self::Cmp32(LocalCmp32Op::I32GtU),
            PureOpKind::I32LeS => Self::Cmp32(LocalCmp32Op::I32LeS),
            PureOpKind::I32LeU => Self::Cmp32(LocalCmp32Op::I32LeU),
            PureOpKind::I32GeS => Self::Cmp32(LocalCmp32Op::I32GeS),
            PureOpKind::I32GeU => Self::Cmp32(LocalCmp32Op::I32GeU),
            PureOpKind::I64Eq => Self::Cmp64(LocalCmp64Op::I64Eq),
            PureOpKind::I64Ne => Self::Cmp64(LocalCmp64Op::I64Ne),
            PureOpKind::I64LtS => Self::Cmp64(LocalCmp64Op::I64LtS),
            PureOpKind::I64LtU => Self::Cmp64(LocalCmp64Op::I64LtU),
            PureOpKind::I64GtS => Self::Cmp64(LocalCmp64Op::I64GtS),
            PureOpKind::I64GtU => Self::Cmp64(LocalCmp64Op::I64GtU),
            PureOpKind::I64LeS => Self::Cmp64(LocalCmp64Op::I64LeS),
            PureOpKind::I64LeU => Self::Cmp64(LocalCmp64Op::I64LeU),
            PureOpKind::I64GeS => Self::Cmp64(LocalCmp64Op::I64GeS),
            PureOpKind::I64GeU => Self::Cmp64(LocalCmp64Op::I64GeU),
            PureOpKind::F32Eq => Self::Cmp32(LocalCmp32Op::F32Eq),
            PureOpKind::F32Ne => Self::Cmp32(LocalCmp32Op::F32Ne),
            PureOpKind::F32Lt => Self::Cmp32(LocalCmp32Op::F32Lt),
            PureOpKind::F32Gt => Self::Cmp32(LocalCmp32Op::F32Gt),
            PureOpKind::F32Le => Self::Cmp32(LocalCmp32Op::F32Le),
            PureOpKind::F32Ge => Self::Cmp32(LocalCmp32Op::F32Ge),
            PureOpKind::F64Eq => Self::Cmp64(LocalCmp64Op::F64Eq),
            PureOpKind::F64Ne => Self::Cmp64(LocalCmp64Op::F64Ne),
            PureOpKind::F64Lt => Self::Cmp64(LocalCmp64Op::F64Lt),
            PureOpKind::F64Gt => Self::Cmp64(LocalCmp64Op::F64Gt),
            PureOpKind::F64Le => Self::Cmp64(LocalCmp64Op::F64Le),
            PureOpKind::F64Ge => Self::Cmp64(LocalCmp64Op::F64Ge),
            _ => return None,
        })
    }

    const fn input_size(self) -> u32 {
        match self {
            Self::Binop32(_) | Self::Cmp32(_) => 4,
            Self::Binop64(_) | Self::Cmp64(_) => 8,
        }
    }

    const fn rhs_const_kind(self) -> LocalFastConstKind {
        match self {
            Self::Binop32(op) => op.const_kind(),
            Self::Binop64(op) => op.const_kind(),
            Self::Cmp32(op) => op.const_kind(),
            Self::Cmp64(op) => op.const_kind(),
        }
    }

    const fn allows_br_if(self) -> bool {
        match self {
            Self::Binop32(op) => matches!(
                op,
                LocalBinop32Op::I32Add
                    | LocalBinop32Op::I32Sub
                    | LocalBinop32Op::I32Mul
                    | LocalBinop32Op::I32And
                    | LocalBinop32Op::I32Or
                    | LocalBinop32Op::I32Xor
                    | LocalBinop32Op::I32Shl
                    | LocalBinop32Op::I32ShrS
                    | LocalBinop32Op::I32ShrU
                    | LocalBinop32Op::I32Rotl
                    | LocalBinop32Op::I32Rotr
            ),
            Self::Cmp32(_) | Self::Cmp64(_) => true,
            Self::Binop64(_) => false,
        }
    }

    fn encode_kind(self, rhs_shape: LocalFastRhsShape) -> u32 {
        match self {
            Self::Binop32(op) => encode_local_binop32_kind(op, rhs_shape),
            Self::Binop64(op) => encode_local_binop64_kind(op, rhs_shape),
            Self::Cmp32(op) => encode_local_cmp32_kind(op, rhs_shape),
            Self::Cmp64(op) => encode_local_cmp64_kind(op, rhs_shape),
        }
    }

    const fn root_op(self) -> Op {
        match self {
            Self::Binop32(_) => vm::op_local_binop32 as Op,
            Self::Binop64(_) => vm::op_local_binop64 as Op,
            Self::Cmp32(_) => vm::op_local_cmp32 as Op,
            Self::Cmp64(_) => vm::op_local_cmp64 as Op,
        }
    }

    const fn set_op(self) -> Op {
        match self {
            Self::Binop32(_) => vm::op_local_binop32_set4 as Op,
            Self::Binop64(_) => vm::op_local_binop64_set8 as Op,
            Self::Cmp32(_) => vm::op_local_cmp32_set4 as Op,
            Self::Cmp64(_) => vm::op_local_cmp64_set4 as Op,
        }
    }

    const fn tee_op(self) -> Op {
        match self {
            Self::Binop32(_) => vm::op_local_binop32_tee4 as Op,
            Self::Binop64(_) => vm::op_local_binop64_tee8 as Op,
            Self::Cmp32(_) => vm::op_local_cmp32_tee4 as Op,
            Self::Cmp64(_) => vm::op_local_cmp64_tee4 as Op,
        }
    }

    const fn br_if_op(self) -> Option<Op> {
        match self {
            Self::Binop32(_) if self.allows_br_if() => Some(vm::op_local_binop32_br_if as Op),
            Self::Cmp32(_) => Some(vm::op_local_cmp32_br_if as Op),
            Self::Cmp64(_) => Some(vm::op_local_cmp64_br_if as Op),
            Self::Binop64(_) | Self::Binop32(_) => None,
        }
    }

    fn flipped(self) -> Option<Self> {
        match self {
            Self::Cmp32(LocalCmp32Op::I32Eq) => Some(Self::Cmp32(LocalCmp32Op::I32Eq)),
            Self::Cmp32(LocalCmp32Op::I32Ne) => Some(Self::Cmp32(LocalCmp32Op::I32Ne)),
            Self::Cmp32(LocalCmp32Op::I32LtS) => Some(Self::Cmp32(LocalCmp32Op::I32GtS)),
            Self::Cmp32(LocalCmp32Op::I32LtU) => Some(Self::Cmp32(LocalCmp32Op::I32GtU)),
            Self::Cmp32(LocalCmp32Op::I32GtS) => Some(Self::Cmp32(LocalCmp32Op::I32LtS)),
            Self::Cmp32(LocalCmp32Op::I32GtU) => Some(Self::Cmp32(LocalCmp32Op::I32LtU)),
            Self::Cmp32(LocalCmp32Op::I32LeS) => Some(Self::Cmp32(LocalCmp32Op::I32GeS)),
            Self::Cmp32(LocalCmp32Op::I32LeU) => Some(Self::Cmp32(LocalCmp32Op::I32GeU)),
            Self::Cmp32(LocalCmp32Op::I32GeS) => Some(Self::Cmp32(LocalCmp32Op::I32LeS)),
            Self::Cmp32(LocalCmp32Op::I32GeU) => Some(Self::Cmp32(LocalCmp32Op::I32LeU)),
            Self::Cmp32(LocalCmp32Op::F32Eq) => Some(Self::Cmp32(LocalCmp32Op::F32Eq)),
            Self::Cmp32(LocalCmp32Op::F32Ne) => Some(Self::Cmp32(LocalCmp32Op::F32Ne)),
            Self::Cmp32(LocalCmp32Op::F32Lt) => Some(Self::Cmp32(LocalCmp32Op::F32Gt)),
            Self::Cmp32(LocalCmp32Op::F32Gt) => Some(Self::Cmp32(LocalCmp32Op::F32Lt)),
            Self::Cmp32(LocalCmp32Op::F32Le) => Some(Self::Cmp32(LocalCmp32Op::F32Ge)),
            Self::Cmp32(LocalCmp32Op::F32Ge) => Some(Self::Cmp32(LocalCmp32Op::F32Le)),
            Self::Cmp64(LocalCmp64Op::I64Eq) => Some(Self::Cmp64(LocalCmp64Op::I64Eq)),
            Self::Cmp64(LocalCmp64Op::I64Ne) => Some(Self::Cmp64(LocalCmp64Op::I64Ne)),
            Self::Cmp64(LocalCmp64Op::I64LtS) => Some(Self::Cmp64(LocalCmp64Op::I64GtS)),
            Self::Cmp64(LocalCmp64Op::I64LtU) => Some(Self::Cmp64(LocalCmp64Op::I64GtU)),
            Self::Cmp64(LocalCmp64Op::I64GtS) => Some(Self::Cmp64(LocalCmp64Op::I64LtS)),
            Self::Cmp64(LocalCmp64Op::I64GtU) => Some(Self::Cmp64(LocalCmp64Op::I64LtU)),
            Self::Cmp64(LocalCmp64Op::I64LeS) => Some(Self::Cmp64(LocalCmp64Op::I64GeS)),
            Self::Cmp64(LocalCmp64Op::I64LeU) => Some(Self::Cmp64(LocalCmp64Op::I64GeU)),
            Self::Cmp64(LocalCmp64Op::I64GeS) => Some(Self::Cmp64(LocalCmp64Op::I64LeS)),
            Self::Cmp64(LocalCmp64Op::I64GeU) => Some(Self::Cmp64(LocalCmp64Op::I64LeU)),
            Self::Cmp64(LocalCmp64Op::F64Eq) => Some(Self::Cmp64(LocalCmp64Op::F64Eq)),
            Self::Cmp64(LocalCmp64Op::F64Ne) => Some(Self::Cmp64(LocalCmp64Op::F64Ne)),
            Self::Cmp64(LocalCmp64Op::F64Lt) => Some(Self::Cmp64(LocalCmp64Op::F64Gt)),
            Self::Cmp64(LocalCmp64Op::F64Gt) => Some(Self::Cmp64(LocalCmp64Op::F64Lt)),
            Self::Cmp64(LocalCmp64Op::F64Le) => Some(Self::Cmp64(LocalCmp64Op::F64Ge)),
            Self::Cmp64(LocalCmp64Op::F64Ge) => Some(Self::Cmp64(LocalCmp64Op::F64Le)),
            Self::Binop32(_) | Self::Binop64(_) => None,
        }
    }

    const fn is_commutative(self) -> bool {
        match self {
            Self::Binop32(op) => matches!(
                op,
                LocalBinop32Op::I32Add
                    | LocalBinop32Op::I32Mul
                    | LocalBinop32Op::I32And
                    | LocalBinop32Op::I32Or
                    | LocalBinop32Op::I32Xor
                    | LocalBinop32Op::F32Add
                    | LocalBinop32Op::F32Mul
            ),
            Self::Binop64(op) => matches!(
                op,
                LocalBinop64Op::I64Add
                    | LocalBinop64Op::I64Mul
                    | LocalBinop64Op::I64And
                    | LocalBinop64Op::I64Or
                    | LocalBinop64Op::I64Xor
                    | LocalBinop64Op::F64Add
                    | LocalBinop64Op::F64Mul
            ),
            Self::Cmp32(op) => matches!(
                op,
                LocalCmp32Op::I32Eq
                    | LocalCmp32Op::I32Ne
                    | LocalCmp32Op::F32Eq
                    | LocalCmp32Op::F32Ne
            ),
            Self::Cmp64(op) => matches!(
                op,
                LocalCmp64Op::I64Eq
                    | LocalCmp64Op::I64Ne
                    | LocalCmp64Op::F64Eq
                    | LocalCmp64Op::F64Ne
            ),
        }
    }
}

#[derive(Clone, Copy)]
struct NumericSelectorRootMatch {
    kind: NumericSelectorRootKind,
    lhs: BlockOperand,
    rhs: BlockOperand,
}

fn match_unary_selector_root_shape(
    graph: &ValueGraph,
    body: &BlockBody,
    root_idx: usize,
    next_idx: usize,
) -> Option<(UnarySelectorRootMatch, ValueRef, Option<usize>)> {
    let root_op = body.ops.get(root_idx)?;
    let BlockOpKind::PureUnary(pure_op) = root_op.kind else {
        return None;
    };
    let kind = UnarySelectorRootKind::from_pure_op(pure_op)?;
    if !block_op_single_use(graph, root_op) {
        return None;
    }
    let root_value = block_op_single_result(root_op)?;
    if value_feeds_memory_address(body, next_idx, root_value) {
        return None;
    }
    let input = *root_op.inputs.first()?;
    if producer_op_index_before(body, input, root_idx).is_none() {
        return Some((
            UnarySelectorRootMatch {
                kind,
                src: selector_value_slot_ref_operand(graph, input, kind.input_size())?,
            },
            root_value,
            None,
        ));
    }
    let provider_idx = root_idx.checked_sub(1)?;
    let provider = body.ops.get(provider_idx)?;
    if block_op_single_result(provider) != Some(input)
        || local_get_reads_block_argument(graph, provider)
    {
        return None;
    }
    Some((
        UnarySelectorRootMatch {
            kind,
            src: selector_non_block_argument_local_get_operand(graph, provider, kind.input_size())?,
        },
        root_value,
        Some(provider_idx),
    ))
}

fn match_selector_root_shape(
    graph: &ValueGraph,
    body: &BlockBody,
    cursor: usize,
    next_idx: usize,
) -> Option<(SelectorRootMatch, ValueRef)> {
    let ops = &body.ops;
    let root_op = ops.get(cursor + 2)?;
    if !block_op_single_use(graph, root_op) {
        return None;
    }
    let root_value = block_op_single_result(root_op)?;
    if value_feeds_memory_address(body, next_idx, root_value) {
        return None;
    }
    match graph[root_value.0].loop_value_shape.as_ref() {
        Some(LoopValueShape::Local4ConstAdd { base, imm }) => {
            let base_operand = selector_local_input_operand(graph, ops.get(cursor)?, *base)?;
            let const_op = ops.get(cursor + 1)?;
            let expected_imm = selector_const_delta(root_op, const_op)?;
            if *imm != expected_imm {
                return None;
            }
            Some((
                SelectorRootMatch::LocalConstAdd {
                    base: base_operand,
                    imm: *imm,
                },
                root_value,
            ))
        }
        Some(LoopValueShape::Local4Local4Add { lhs, rhs }) => {
            if root_op.kind != BlockOpKind::PureBinary(PureOpKind::I32Add) {
                return None;
            }
            let lhs_operand = selector_local_input_operand(graph, ops.get(cursor)?, *lhs)?;
            let rhs_operand = selector_local_input_operand(graph, ops.get(cursor + 1)?, *rhs)?;
            Some((
                SelectorRootMatch::LocalLocalAdd {
                    lhs: lhs_operand,
                    rhs: rhs_operand,
                },
                root_value,
            ))
        }
        _ => match_selector_root_shape_from_body(
            graph,
            root_op,
            ops.get(cursor)?,
            ops.get(cursor + 1)?,
        )
        .map(|matched| (matched, root_value)),
    }
}

fn match_numeric_selector_root_shape(
    graph: &ValueGraph,
    body: &BlockBody,
    cursor: usize,
    next_idx: usize,
) -> Option<(NumericSelectorRootMatch, ValueRef)> {
    let ops = &body.ops;
    let root_op = ops.get(cursor + 2)?;
    if !block_op_single_use(graph, root_op) {
        return None;
    }
    let root_value = block_op_single_result(root_op)?;
    if value_feeds_memory_address(body, next_idx, root_value) {
        return None;
    }
    match_numeric_selector_root_shape_from_body(
        graph,
        root_op,
        ops.get(cursor)?,
        ops.get(cursor + 1)?,
    )
    .map(|matched| (matched, root_value))
}

fn match_numeric_selector_root_shape_from_body(
    graph: &ValueGraph,
    root_op: &BlockOp,
    first: &BlockOp,
    second: &BlockOp,
) -> Option<NumericSelectorRootMatch> {
    let BlockOpKind::PureBinary(pure_op) = root_op.kind else {
        return None;
    };
    let kind = NumericSelectorRootKind::from_pure_op(pure_op)?;
    let input_size = kind.input_size();
    let const_kind = kind.rhs_const_kind();

    if let (Some(lhs), Some(rhs)) = (
        selector_non_block_argument_local_get_operand(graph, first, input_size),
        selector_non_block_argument_local_get_operand(graph, second, input_size),
    ) {
        return Some(NumericSelectorRootMatch { kind, lhs, rhs });
    }

    if let (Some(lhs), Some(rhs)) = (
        selector_non_block_argument_local_get_operand(graph, first, input_size),
        block_op_const_operand_of_kind(second, const_kind),
    ) {
        return Some(NumericSelectorRootMatch { kind, lhs, rhs });
    }

    if let (Some(lhs), Some(rhs)) = (
        block_op_const_operand_of_kind(first, const_kind),
        selector_non_block_argument_local_get_operand(graph, second, input_size),
    ) {
        if kind.is_commutative() {
            return Some(NumericSelectorRootMatch {
                kind,
                lhs: rhs,
                rhs: lhs,
            });
        }
        if let Some(flipped) = kind.flipped() {
            return Some(NumericSelectorRootMatch {
                kind: flipped,
                lhs: rhs,
                rhs: lhs,
            });
        }
    }

    None
}

fn match_selector_root_shape_from_body(
    graph: &ValueGraph,
    root_op: &BlockOp,
    first: &BlockOp,
    second: &BlockOp,
) -> Option<SelectorRootMatch> {
    if let Some(base) = selector_non_block_argument_local_get4_operand(graph, first) {
        if let Some(imm) = selector_const_delta(root_op, second) {
            return Some(SelectorRootMatch::LocalConstAdd { base, imm });
        }
    }
    if root_op.kind == BlockOpKind::PureBinary(PureOpKind::I32Add) {
        if let Some(base) = selector_non_block_argument_local_get4_operand(graph, second) {
            if let Some(imm) = block_op_i32_const(first) {
                return Some(SelectorRootMatch::LocalConstAdd { base, imm });
            }
        }
        if let (Some(lhs), Some(rhs)) = (
            selector_non_block_argument_local_get4_operand(graph, first),
            selector_non_block_argument_local_get4_operand(graph, second),
        ) {
            return Some(SelectorRootMatch::LocalLocalAdd { lhs, rhs });
        }
    }
    None
}

fn selector_local_input_operand(
    graph: &ValueGraph,
    op: &BlockOp,
    expected_slot: LocalSlot,
) -> Option<BlockOperand> {
    if op.kind != BlockOpKind::LocalGet {
        return None;
    }
    let value = block_op_single_result(op)?;
    let node = &graph[value.0];
    if node.use_count > 1 {
        return None;
    }
    let matches_expected_slot = node
        .loop_value_shape
        .as_ref()
        .and_then(slot_ref_from_loop_value_shape)
        .or_else(|| effective_slot_shape(graph, value).and_then(|shape| shape.slot))
        .and_then(materializable_slot)
        .is_some_and(|slot| slot == expected_slot);
    if !matches_expected_slot {
        return None;
    }
    let size = local_get_size_from_op(op.op)?;
    match *op.operands.first()? {
        BlockOperand::LocalAddr(addr) if expected_slot.addr == addr && expected_slot.size == 4 => {
            if node.is_effect_result() {
                return None;
            }
            Some(BlockOperand::LocalAddr(addr))
        }
        BlockOperand::SpillValue(source)
            if size == 4 && expected_slot == symbolic_spill_slot(source, size) =>
        {
            Some(BlockOperand::SpillValue(source))
        }
        _ => None,
    }
}

fn const_operand_matches_kind(operand: BlockOperand, kind: LocalFastConstKind) -> bool {
    matches!(
        (operand, kind),
        (BlockOperand::I32(_), LocalFastConstKind::I32)
            | (BlockOperand::I64(_), LocalFastConstKind::I64)
            | (BlockOperand::F32(_), LocalFastConstKind::F32)
            | (BlockOperand::F64(_), LocalFastConstKind::F64)
    )
}

fn block_op_const_operand_of_kind(op: &BlockOp, kind: LocalFastConstKind) -> Option<BlockOperand> {
    if op.kind != BlockOpKind::Const {
        return None;
    }
    let operand = *op.operands.first()?;
    const_operand_matches_kind(operand, kind).then_some(operand)
}

fn selector_any_local_get_operand(op: &BlockOp, expected_size: u32) -> Option<BlockOperand> {
    if op.kind != BlockOpKind::LocalGet || local_get_size_from_op(op.op)? != expected_size {
        return None;
    }
    match *op.operands.first()? {
        BlockOperand::LocalAddr(addr) => Some(BlockOperand::LocalAddr(addr)),
        BlockOperand::SpillValue(source) => Some(BlockOperand::SpillValue(source)),
        _ => None,
    }
}

fn selector_non_block_argument_local_get_operand(
    graph: &ValueGraph,
    op: &BlockOp,
    expected_size: u32,
) -> Option<BlockOperand> {
    let value = block_op_single_result(op)?;
    if local_get_result_is_non_lossless_block_argument(graph, value) {
        return None;
    }
    selector_any_local_get_operand(op, expected_size)
}

fn selector_any_local_get4_operand(op: &BlockOp) -> Option<BlockOperand> {
    selector_any_local_get_operand(op, 4)
}

fn selector_non_block_argument_local_get4_operand(
    graph: &ValueGraph,
    op: &BlockOp,
) -> Option<BlockOperand> {
    selector_non_block_argument_local_get_operand(graph, op, 4)
}

fn local_get_reads_block_argument(graph: &ValueGraph, op: &BlockOp) -> bool {
    op.kind == BlockOpKind::LocalGet
        && block_op_single_result(op)
            .is_some_and(|value| local_get_result_is_non_lossless_block_argument(graph, value))
}

fn local_get_result_is_non_lossless_block_argument(graph: &ValueGraph, value: ValueRef) -> bool {
    let node = &graph[value.0];
    if node.origin.kind != ExprOriginKind::BlockArgument && !node.is_block_argument() {
        return false;
    }
    node.address_shape.is_none()
        && node.loop_value_shape.is_none()
        && node.const_value.is_none()
        && node.key.is_none()
}

fn selector_const_delta(root_op: &BlockOp, const_op: &BlockOp) -> Option<i32> {
    let imm = block_op_i32_const(const_op)?;
    match root_op.kind {
        BlockOpKind::PureBinary(PureOpKind::I32Add) => Some(imm),
        BlockOpKind::PureBinary(PureOpKind::I32Sub) => Some(imm.wrapping_neg()),
        _ => None,
    }
}

fn match_br_if_pattern(
    graph: &ValueGraph,
    body: &BlockBody,
    terminator: &BlockTerminator,
) -> Option<(BlockTerminator, usize)> {
    let condition = *terminator.inputs.first()?;
    if graph[condition.0].needs_spill {
        return None;
    }
    if graph[condition.0].is_effect_result()
        && !last_op_is_spill_local_get_for_value(body, condition)
    {
        return None;
    }

    if let Some((mut matched, consumed)) = match_br_if_tee_pattern(graph, body, condition) {
        matched.insert(0, branch_target_operand(terminator)?);
        return Some((
            fused_br_if_terminator(
                terminator,
                vm::op_local_get4_i32_const_add_tee4_br_if as Op,
                matched,
            ),
            consumed,
        ));
    }

    if body.ops.len() >= 3 {
        if let Some((matched, root_value)) =
            match_numeric_selector_root_shape(graph, body, body.ops.len() - 3, body.ops.len())
        {
            if root_value == condition && matched.kind.allows_br_if() {
                let mut operands = vec![branch_target_operand(terminator)?];
                operands.extend(numeric_root_operands(matched));
                let op = matched.kind.br_if_op()?;
                return Some((fused_br_if_terminator(terminator, op, operands), 3));
            }
        }
        if let Some((matched, root_value)) =
            match_selector_root_shape(graph, body, body.ops.len() - 3, body.ops.len())
        {
            if root_value == condition {
                let (op, operands) = match matched {
                    SelectorRootMatch::LocalConstAdd { base, imm } => (
                        vm::op_local_get4_i32_const_add_br_if as Op,
                        vec![
                            branch_target_operand(terminator)?,
                            base,
                            BlockOperand::I32(imm),
                        ],
                    ),
                    SelectorRootMatch::LocalLocalAdd { lhs, rhs } => (
                        vm::op_local_get4_local_get4_i32_add_br_if as Op,
                        vec![branch_target_operand(terminator)?, lhs, rhs],
                    ),
                };
                return Some((fused_br_if_terminator(terminator, op, operands), 3));
            }
        }
    }

    if let Some((compare, consumed)) = match_compare_br_if_pattern(graph, body, condition) {
        let (op, operands) = match compare {
            SelectorCompareMatch::Eqz { input } => (
                vm::op_local_get4_i32_eqz_br_if as Op,
                vec![branch_target_operand(terminator)?, input],
            ),
            SelectorCompareMatch::Const { lhs, cmp_kind, imm } => (
                vm::op_local_get4_i32_const_compare_br_if as Op,
                vec![
                    branch_target_operand(terminator)?,
                    lhs,
                    BlockOperand::U32(cmp_kind),
                    BlockOperand::I32(imm),
                ],
            ),
            SelectorCompareMatch::Local { lhs, rhs, cmp_kind } => (
                vm::op_local_get4_local_get4_compare_br_if as Op,
                vec![
                    branch_target_operand(terminator)?,
                    lhs,
                    rhs,
                    BlockOperand::U32(cmp_kind),
                ],
            ),
        };
        return Some((fused_br_if_terminator(terminator, op, operands), consumed));
    }

    let local_get = body.ops.last()?;
    let operand = selector_any_local_get4_operand(local_get)?;
    let value = block_op_single_result(local_get)?;
    if value != condition || value_feeds_memory_address(body, body.ops.len(), value) {
        return None;
    }
    Some((
        fused_br_if_terminator(
            terminator,
            vm::op_local_get4_br_if as Op,
            vec![branch_target_operand(terminator)?, operand],
        ),
        1,
    ))
}

fn match_br_if_tee_pattern(
    graph: &ValueGraph,
    body: &BlockBody,
    condition: ValueRef,
) -> Option<(Vec<BlockOperand>, usize)> {
    if body.ops.len() < 4 {
        return None;
    }
    let tee = body.ops.last()?;
    if tee.kind != BlockOpKind::LocalTee {
        return None;
    }
    let root_start = body.ops.len() - 4;
    let (matched, root_value) = match_selector_root_shape(graph, body, root_start, body.ops.len())?;
    if root_value != condition || value_used_after(body, body.ops.len(), root_value) {
        return None;
    }
    let dst = *tee.operands.first()?;
    let SelectorRootMatch::LocalConstAdd { base, imm } = matched else {
        return None;
    };
    Some((vec![base, BlockOperand::I32(imm), dst], 4))
}

fn match_compare_br_if_pattern(
    graph: &ValueGraph,
    body: &BlockBody,
    condition: ValueRef,
) -> Option<(SelectorCompareMatch, usize)> {
    match graph[condition.0].loop_value_shape.as_ref() {
        Some(LoopValueShape::CompareEqz { input }) => (|| {
            let LoopValueShape::Local4(slot) = input.as_ref() else {
                return None;
            };
            if body.ops.len() < 2 {
                return None;
            }
            let eqz = body.ops.last()?;
            if eqz.kind != BlockOpKind::PureUnary(PureOpKind::I32Eqz)
                || !block_op_single_use(graph, eqz)
                || block_op_single_result(eqz) != Some(condition)
            {
                return None;
            }
            let input_operand =
                selector_local_input_operand(graph, &body.ops[body.ops.len() - 2], *slot)?;
            Some((
                SelectorCompareMatch::Eqz {
                    input: input_operand,
                },
                2,
            ))
        })(),
        Some(LoopValueShape::CompareConstI32 { lhs, op, imm }) => (|| {
            let LoopValueShape::Local4(slot) = lhs.as_ref() else {
                return None;
            };
            if body.ops.len() < 3 {
                return None;
            }
            let compare = body.ops.last()?;
            if compare.kind != BlockOpKind::PureBinary(*op)
                || !block_op_single_use(graph, compare)
                || block_op_single_result(compare) != Some(condition)
            {
                return None;
            }
            let cmp_kind = encode_i32_compare_kind(*op)?;
            let lhs_operand =
                selector_local_input_operand(graph, &body.ops[body.ops.len() - 3], *slot)?;
            let const_op = &body.ops[body.ops.len() - 2];
            if block_op_i32_const(const_op)? != *imm {
                return None;
            }
            Some((
                SelectorCompareMatch::Const {
                    lhs: lhs_operand,
                    cmp_kind,
                    imm: *imm,
                },
                3,
            ))
        })(),
        Some(LoopValueShape::CompareLocal4 { lhs, op, rhs }) => (|| {
            if body.ops.len() < 3 {
                return None;
            }
            let compare = body.ops.last()?;
            if compare.kind != BlockOpKind::PureBinary(*op)
                || !block_op_single_use(graph, compare)
                || block_op_single_result(compare) != Some(condition)
            {
                return None;
            }
            let cmp_kind = encode_i32_compare_kind(*op)?;
            let lhs_operand =
                selector_local_input_operand(graph, &body.ops[body.ops.len() - 3], *lhs)?;
            let rhs_operand =
                selector_local_input_operand(graph, &body.ops[body.ops.len() - 2], *rhs)?;
            Some((
                SelectorCompareMatch::Local {
                    lhs: lhs_operand,
                    rhs: rhs_operand,
                    cmp_kind,
                },
                3,
            ))
        })(),
        _ => None,
    }
    .or_else(|| match_compare_br_if_pattern_from_slot_refs(graph, body, condition))
    .or_else(|| match_compare_br_if_pattern_from_body(graph, body, condition))
}

fn value_defined_in_body_before(body: &BlockBody, consumer_idx: usize, value: ValueRef) -> bool {
    body.ops
        .iter()
        .take(consumer_idx)
        .any(|op| block_op_single_result(op) == Some(value))
}

fn trailing_const_input_consumed(
    body: &BlockBody,
    compare_idx: usize,
    value: ValueRef,
    imm: i32,
) -> Option<usize> {
    let const_idx = compare_idx.checked_sub(1)?;
    let const_op = body.ops.get(const_idx)?;
    (const_op.kind == BlockOpKind::Const
        && block_op_single_result(const_op) == Some(value)
        && block_op_i32_const(const_op) == Some(imm))
    .then_some(2)
}

fn match_compare_br_if_pattern_from_slot_refs(
    graph: &ValueGraph,
    body: &BlockBody,
    condition: ValueRef,
) -> Option<(SelectorCompareMatch, usize)> {
    let compare_idx = body.ops.len().checked_sub(1)?;
    let compare = body.ops.get(compare_idx)?;
    if block_op_single_result(compare) != Some(condition) || !block_op_single_use(graph, compare) {
        return None;
    }
    match compare.kind {
        BlockOpKind::PureUnary(PureOpKind::I32Eqz) => {
            let input = *compare.inputs.first()?;
            if value_defined_in_body_before(body, compare_idx, input) {
                return None;
            }
            let input = selector_value_slot_ref_operand(graph, input, 4)?;
            Some((SelectorCompareMatch::Eqz { input }, 1))
        }
        BlockOpKind::PureBinary(op) if i32_compare_op(op) => {
            let lhs = *compare.inputs.first()?;
            let rhs = *compare.inputs.get(1)?;
            if let (Some(lhs_operand), Some(imm)) = (
                selector_value_slot_ref_operand(graph, lhs, 4),
                i32_const_expr(graph, rhs),
            ) {
                if value_defined_in_body_before(body, compare_idx, lhs) {
                    return None;
                }
                let consumed =
                    trailing_const_input_consumed(body, compare_idx, rhs, imm).or_else(|| {
                        (!value_defined_in_body_before(body, compare_idx, rhs)).then_some(1)
                    })?;
                return Some((
                    SelectorCompareMatch::Const {
                        lhs: lhs_operand,
                        cmp_kind: encode_i32_compare_kind(op)?,
                        imm,
                    },
                    consumed,
                ));
            }
            if let (Some(rhs_operand), Some(imm), Some(flipped)) = (
                selector_value_slot_ref_operand(graph, rhs, 4),
                i32_const_expr(graph, lhs),
                flip_i32_compare_op(op),
            ) {
                if value_defined_in_body_before(body, compare_idx, rhs) {
                    return None;
                }
                let consumed =
                    trailing_const_input_consumed(body, compare_idx, lhs, imm).or_else(|| {
                        (!value_defined_in_body_before(body, compare_idx, lhs)).then_some(1)
                    })?;
                return Some((
                    SelectorCompareMatch::Const {
                        lhs: rhs_operand,
                        cmp_kind: encode_i32_compare_kind(flipped)?,
                        imm,
                    },
                    consumed,
                ));
            }
            if value_defined_in_body_before(body, compare_idx, lhs)
                || value_defined_in_body_before(body, compare_idx, rhs)
            {
                return None;
            }
            let lhs = selector_value_slot_ref_operand(graph, lhs, 4)?;
            let rhs = selector_value_slot_ref_operand(graph, rhs, 4)?;
            Some((
                SelectorCompareMatch::Local {
                    lhs,
                    rhs,
                    cmp_kind: encode_i32_compare_kind(op)?,
                },
                1,
            ))
        }
        _ => None,
    }
}

fn match_compare_br_if_pattern_from_body(
    _graph: &ValueGraph,
    body: &BlockBody,
    _condition: ValueRef,
) -> Option<(SelectorCompareMatch, usize)> {
    if body.ops.len() >= 2 {
        let local_get = &body.ops[body.ops.len() - 2];
        let eqz = body.ops.last()?;
        if eqz.kind == BlockOpKind::PureUnary(PureOpKind::I32Eqz) {
            let operand = selector_any_local_get4_operand(local_get)?;
            return Some((SelectorCompareMatch::Eqz { input: operand }, 2));
        }
    }

    if body.ops.len() < 3 {
        return None;
    }
    let lhs_op = &body.ops[body.ops.len() - 3];
    let rhs_op = &body.ops[body.ops.len() - 2];
    let compare = body.ops.last()?;
    let BlockOpKind::PureBinary(op) = compare.kind else {
        return None;
    };
    if !i32_compare_op(op) {
        return None;
    }
    if let (Some(lhs), Some(imm)) = (
        selector_any_local_get4_operand(lhs_op),
        block_op_i32_const(rhs_op),
    ) {
        return Some((
            SelectorCompareMatch::Const {
                lhs,
                cmp_kind: encode_i32_compare_kind(op)?,
                imm,
            },
            3,
        ));
    }
    if let (Some(rhs), Some(imm), Some(flipped)) = (
        selector_any_local_get4_operand(rhs_op),
        block_op_i32_const(lhs_op),
        flip_i32_compare_op(op),
    ) {
        return Some((
            SelectorCompareMatch::Const {
                lhs: rhs,
                cmp_kind: encode_i32_compare_kind(flipped)?,
                imm,
            },
            3,
        ));
    }
    if let (Some(lhs), Some(rhs)) = (
        selector_any_local_get4_operand(lhs_op),
        selector_any_local_get4_operand(rhs_op),
    ) {
        return Some((
            SelectorCompareMatch::Local {
                lhs,
                rhs,
                cmp_kind: encode_i32_compare_kind(op)?,
            },
            3,
        ));
    }
    None
}

fn branch_target_operand(terminator: &BlockTerminator) -> Option<BlockOperand> {
    let BlockOperand::JumpTarget(target) = *terminator.operands.first()? else {
        return None;
    };
    Some(BlockOperand::JumpTarget(target))
}

fn last_op_is_spill_local_get_for_value(body: &BlockBody, value: ValueRef) -> bool {
    let Some(op) = body.ops.last() else {
        return false;
    };
    op.kind == BlockOpKind::LocalGet
        && block_op_single_result(op) == Some(value)
        && matches!(op.operands.first(), Some(BlockOperand::SpillValue(_)))
}

fn fused_br_if_terminator(
    terminator: &BlockTerminator,
    op: Op,
    mut operands: Vec<BlockOperand>,
) -> BlockTerminator {
    if !matches!(operands.first(), Some(BlockOperand::JumpTarget(_))) {
        let target = branch_target_operand(terminator).expect("br_if terminator must carry target");
        operands.insert(0, target);
    }
    BlockTerminator {
        source_start: terminator.source_start,
        op,
        kind: BlockTerminatorKind::BrIf,
        operands,
        inputs: terminator.inputs.clone(),
        values: terminator.values.clone(),
    }
}

fn encode_i32_compare_kind(op: PureOpKind) -> Option<u32> {
    match op {
        PureOpKind::I32Eq => Some(0),
        PureOpKind::I32Ne => Some(1),
        PureOpKind::I32LtS => Some(2),
        PureOpKind::I32LtU => Some(3),
        PureOpKind::I32GtS => Some(4),
        PureOpKind::I32GtU => Some(5),
        PureOpKind::I32LeS => Some(6),
        PureOpKind::I32LeU => Some(7),
        PureOpKind::I32GeS => Some(8),
        PureOpKind::I32GeU => Some(9),
        _ => None,
    }
}

fn value_used_after(body: &BlockBody, start_idx: usize, value: ValueRef) -> bool {
    value_use_count_after(body, start_idx, value) > 0
}

fn value_use_count_after(body: &BlockBody, start_idx: usize, value: ValueRef) -> usize {
    body.ops
        .iter()
        .skip(start_idx)
        .map(|op| op.inputs.iter().filter(|input| **input == value).count())
        .sum::<usize>()
        + if start_idx < body.ops.len() {
            body.terminator
                .as_ref()
                .map(|terminator| {
                    terminator
                        .inputs
                        .iter()
                        .filter(|input| **input == value)
                        .count()
                })
                .unwrap_or_default()
        } else {
            0
        }
}

fn next_entry_is_barrier(body: &BlockBody, idx: usize) -> bool {
    if let Some(op) = body.ops.get(idx) {
        return matches!(
            op.kind,
            BlockOpKind::CallLike
                | BlockOpKind::GlobalGet
                | BlockOpKind::GlobalSet
                | BlockOpKind::TableGet
                | BlockOpKind::TableSet
                | BlockOpKind::MemoryLoad
                | BlockOpKind::MemoryStore
                | BlockOpKind::Select
                | BlockOpKind::Raw
        );
    }
    body.terminator.is_some()
}

#[cfg_attr(not(test), allow(dead_code))]
fn br_if_candidate_shape(graph: &ValueGraph, condition: ValueRef) -> Option<LoopValueShape> {
    let candidate = graph[condition.0].loop_value_shape.clone().or_else(|| {
        effective_slot_shape(graph, condition)
            .and_then(|shape| shape.slot)
            .and_then(materializable_slot)
            .filter(|slot| slot.size == 4)
            .map(LoopValueShape::Local4)
    })?;
    match &candidate {
        LoopValueShape::Local4(_)
        | LoopValueShape::Local4ConstAdd { .. }
        | LoopValueShape::Local4Local4Add { .. }
        | LoopValueShape::CompareEqz { .. }
        | LoopValueShape::CompareConstI32 { .. }
        | LoopValueShape::CompareLocal4 { .. } => Some(candidate),
    }
}

fn reachable_blocks(program: &BasicBlockProgram, bodies: &[BlockBody]) -> Vec<bool> {
    let mut reachable = vec![false; program.blocks.len()];
    let mut queue = VecDeque::from([0usize]);
    while let Some(block_id) = queue.pop_front() {
        if reachable[block_id] {
            continue;
        }
        reachable[block_id] = true;
        for succ in rewritten_successors(program, block_id, &bodies[block_id]) {
            if !reachable[succ] {
                queue.push_back(succ);
            }
        }
    }
    reachable
}

fn rewritten_successors(
    program: &BasicBlockProgram,
    block_id: usize,
    body: &BlockBody,
) -> Vec<usize> {
    let fallthrough = program.next_block_id(block_id);
    let Some(last) = &body.terminator else {
        return fallthrough.into_iter().collect();
    };
    match last.kind {
        BlockTerminatorKind::Br | BlockTerminatorKind::Else | BlockTerminatorKind::Return => {
            return single_target(program, last).into_iter().collect();
        }
        BlockTerminatorKind::BrIf | BlockTerminatorKind::If => {
            let mut succs = Vec::new();
            if let Some(target) = single_target(program, last) {
                succs.push(target);
            }
            if let Some(next) = fallthrough {
                succs.push(next);
            }
            succs.sort_unstable();
            succs.dedup();
            return succs;
        }
        BlockTerminatorKind::BrTable => return table_targets(program, last),
        BlockTerminatorKind::SpecialFunctionReturn => return Vec::new(),
        BlockTerminatorKind::SpecialBlockReturn => return fallthrough.into_iter().collect(),
        BlockTerminatorKind::Unreachable => return Vec::new(),
        _ => {}
    }
    fallthrough.into_iter().collect()
}

fn single_target(program: &BasicBlockProgram, terminator: &BlockTerminator) -> Option<usize> {
    let BlockOperand::JumpTarget(target) = *terminator.operands.first()? else {
        return None;
    };
    program.block_for_old_start(target)
}

fn table_targets(program: &BasicBlockProgram, terminator: &BlockTerminator) -> Vec<usize> {
    let Some(BlockOperand::U32(table_len)) = terminator.operands.first() else {
        return Vec::new();
    };
    let table_len = *table_len as usize;
    (1..=table_len + 1)
        .filter_map(|idx| {
            let BlockOperand::JumpTarget(target) = terminator.operands[idx] else {
                return None;
            };
            program.block_for_old_start(target)
        })
        .collect()
}

#[cfg(test)]
pub(crate) fn patch_jump_targets(records: &mut [RecordEmit]) -> Result<(), ()> {
    let mut old_to_new = HashMap::new();
    let mut cursor = 0usize;
    let mut record_positions = Vec::with_capacity(records.len());
    for record in records.iter() {
        record_positions.push((record.source_start, cursor));
        if let Some(old_start) = record.source_start {
            old_to_new.entry(old_start).or_insert(cursor);
        }
        cursor += record.len();
    }
    for record in records.iter_mut() {
        if let Some(target_index) = record_jump_target_operand_index(record.op) {
            let target = unsafe { record.operands[target_index].jump_addr as usize };
            let Some(patched) = old_to_new
                .get(&target)
                .copied()
                .or_else(|| infer_missing_target_cursor(&record_positions, target))
            else {
                return Err(());
            };
            record.operands[target_index] = Operand {
                jump_addr: patched as u32,
            };
        } else if std::ptr::fn_addr_eq(record.op, vm::op_br_table as Op) {
            let table_len = unsafe { record.operands[0].u32 as usize };
            for idx in 1..=table_len + 1 {
                let target = unsafe { record.operands[idx].jump_addr as usize };
                let Some(patched) = old_to_new.get(&target).copied() else {
                    return Err(());
                };
                record.operands[idx] = Operand {
                    jump_addr: patched as u32,
                };
            }
        }
    }
    Ok(())
}

fn patch_packed_jump_targets(ops: &mut [PackedOp]) -> Result<(), ()> {
    let mut old_to_new = HashMap::new();
    let mut cursor = 0usize;
    let mut record_positions = Vec::with_capacity(ops.len());
    for op in ops.iter() {
        record_positions.push((op.source_start, cursor));
        if let Some(old_start) = op.source_start {
            old_to_new.entry(old_start).or_insert(cursor);
        }
        cursor += op.len();
    }
    for op in ops.iter_mut() {
        if let Some(target_index) = record_jump_target_operand_index(op.op) {
            let Some(PackedOperand::JumpTarget(target)) = op.operands.get(target_index).copied()
            else {
                return Err(());
            };
            let Some(patched) = old_to_new
                .get(&(target as usize))
                .copied()
                .or_else(|| infer_missing_target_cursor(&record_positions, target as usize))
            else {
                return Err(());
            };
            op.operands[target_index] = PackedOperand::JumpTarget(patched as u32);
        } else if std::ptr::fn_addr_eq(op.op, vm::op_br_table as Op) {
            let Some(PackedOperand::U32(table_len)) = op.operands.first().copied() else {
                return Err(());
            };
            for idx in 1..=table_len as usize + 1 {
                let Some(PackedOperand::JumpTarget(target)) = op.operands.get(idx).copied() else {
                    return Err(());
                };
                let Some(patched) = old_to_new.get(&(target as usize)).copied() else {
                    return Err(());
                };
                op.operands[idx] = PackedOperand::JumpTarget(patched as u32);
            }
        }
    }
    Ok(())
}

fn infer_missing_target_cursor(
    record_positions: &[(Option<usize>, usize)],
    target: usize,
) -> Option<usize> {
    let next_known = record_positions
        .iter()
        .position(|(source_start, _)| source_start.is_some_and(|start| start > target))?;
    let first_unknown_before_next = record_positions[..next_known]
        .iter()
        .rposition(|(source_start, _)| source_start.is_some())
        .map_or(0, |idx| idx + 1);
    if let Some(cursor) = record_positions
        .get(first_unknown_before_next..next_known)?
        .iter()
        .find(|(source_start, _)| source_start.is_none())
        .map(|(_, cursor)| *cursor)
    {
        return Some(cursor);
    }
    record_positions.get(next_known).map(|(_, cursor)| *cursor)
}

fn record_jump_target_operand_index(op: Op) -> Option<usize> {
    if std::ptr::fn_addr_eq(op, vm::op_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_else as Op)
        || std::ptr::fn_addr_eq(op, vm::op_br as Op)
        || std::ptr::fn_addr_eq(op, vm::op_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_return as Op)
    {
        return Some(0);
    }
    if std::ptr::fn_addr_eq(op, vm::op_local_get4_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_get4_i32_eqz_br_if as Op)
    {
        return Some(1);
    }
    if std::ptr::fn_addr_eq(op, vm::op_local_get4_i32_const_add_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_get4_local_get4_i32_add_br_if as Op)
    {
        return Some(2);
    }
    if std::ptr::fn_addr_eq(op, vm::op_local_get4_i32_const_compare_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_get4_local_get4_compare_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_get4_i32_const_add_tee4_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_binop32_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_cmp32_br_if as Op)
        || std::ptr::fn_addr_eq(op, vm::op_local_cmp64_br_if as Op)
    {
        return Some(3);
    }
    None
}

fn verify_explicit_effect_ir(program: &BasicBlockProgram, bodies: &[BlockBody]) -> bool {
    let reachable = reachable_blocks(program, bodies);
    verify_barrier_op_counts(program, &reachable, |source_start, op| {
        count_explicit_ir_ops(bodies, source_start, op)
    })
}

fn verify_slot_plan(program: &BasicBlockProgram, rewrite: &FunctionRewrite) -> bool {
    for block in &program.blocks {
        let entry = &rewrite.entries[block.id];
        if !entry.reachable {
            continue;
        }
        let mut incoming = Vec::new();
        if block.id == 0 {
            continue;
        }
        for pred in &program.predecessors[block.id] {
            let pred_state = &rewrite.exits[*pred];
            if pred_state.reachable {
                incoming.push(pred_state);
            }
        }
        if incoming.is_empty() {
            continue;
        }
        let copy_plan = &rewrite.relower.block_copy_plans[block.id];
        for (ordinal, merged) in entry.stack.iter().copied().enumerate() {
            let values = incoming
                .iter()
                .map(|state| state.stack.get(ordinal))
                .collect::<Vec<_>>();
            if slot_merge_decision(&rewrite.graph, &values, merged)
                != copy_plan.stack.get(&ordinal).copied()
            {
                return false;
            }
        }
        for (slot, merged) in &entry.locals {
            if !rewrite.graph[merged.0].is_block_argument() {
                continue;
            }
            if rewrite.graph[merged.0]
                .slot_shape
                .as_ref()
                .and_then(|shape| shape.slot)
                != Some(slot_ref_for_local_slot(*slot))
            {
                return false;
            }
            if copy_plan.locals.get(slot) != Some(&SlotMergeDecision::Preserve) {
                return false;
            }
        }
        for (key, merged) in &entry.aliases {
            let values = incoming
                .iter()
                .map(|state| state.aliases.get(key))
                .collect::<Vec<_>>();
            if slot_merge_decision(&rewrite.graph, &values, *merged)
                != copy_plan.aliases.get(key).copied()
            {
                return false;
            }
        }
    }
    true
}

#[allow(dead_code)]
fn verify_relower_preserves_call_ops(
    program: &BasicBlockProgram,
    bodies: &[BlockBody],
    ops: &[PackedOp],
) -> bool {
    let reachable = reachable_blocks(program, bodies);
    verify_barrier_op_counts(program, &reachable, |source_start, op| {
        ops.iter()
            .filter(|packed| {
                packed.source_start == Some(source_start) && std::ptr::fn_addr_eq(packed.op, op)
            })
            .count()
    }) && verify_packed_call_operands(ops)
}

fn verify_packed_call_operands(ops: &[PackedOp]) -> bool {
    for op in ops {
        if std::ptr::fn_addr_eq(op.op, vm::op_call as Op)
            || std::ptr::fn_addr_eq(op.op, vm::op_call_import as Op)
            || std::ptr::fn_addr_eq(op.op, vm::op_return_call as Op)
            || std::ptr::fn_addr_eq(op.op, vm::op_return_call_import as Op)
        {
            if op.operands.len() != 1
                || !matches!(op.operands.first(), Some(PackedOperand::CallRecipeRef(_)))
            {
                return false;
            }
            continue;
        }
        if (std::ptr::fn_addr_eq(op.op, vm::op_call_indirect as Op)
            || std::ptr::fn_addr_eq(op.op, vm::op_return_call_indirect as Op))
            && (op.operands.len() != 2
                || !op
                    .operands
                    .iter()
                    .all(|operand| matches!(operand, PackedOperand::U32(_))))
        {
            return false;
        }
    }
    true
}

fn verify_effect_result_spill_ir(
    graph: &ValueGraph,
    bodies: &[BlockBody],
    spill_plan: &EffectResultSpillPlan,
) -> bool {
    for body in bodies {
        for op in &body.ops {
            for operand in &op.operands {
                let BlockOperand::SpillValue(source) = *operand else {
                    continue;
                };
                let node = &graph[source.0];
                if !node.is_effect_result()
                    || !node.needs_spill
                    || spill_plan.slot(source).is_none()
                {
                    return false;
                }
            }
        }
        if let Some(terminator) = &body.terminator {
            for operand in &terminator.operands {
                let BlockOperand::SpillValue(source) = *operand else {
                    continue;
                };
                let node = &graph[source.0];
                if !node.is_effect_result()
                    || !node.needs_spill
                    || spill_plan.slot(source).is_none()
                {
                    return false;
                }
            }
        }
    }
    true
}

fn verify_relower_preserves_effect_result_spills(
    graph: &ValueGraph,
    bodies: &[BlockBody],
    spill_plan: &EffectResultSpillPlan,
    ops: &[PackedOp],
) -> bool {
    let mut expected_reads = HashMap::new();
    for body in bodies {
        for op in &body.ops {
            for operand in &op.operands {
                let BlockOperand::SpillValue(source) = *operand else {
                    continue;
                };
                let Some(slot) = spill_plan.slot(source) else {
                    return false;
                };
                *expected_reads
                    .entry((slot.addr, slot.size))
                    .or_insert(0usize) += 1;
            }
        }
        if let Some(terminator) = &body.terminator {
            for operand in &terminator.operands {
                let BlockOperand::SpillValue(source) = *operand else {
                    continue;
                };
                let Some(slot) = spill_plan.slot(source) else {
                    return false;
                };
                *expected_reads
                    .entry((slot.addr, slot.size))
                    .or_insert(0usize) += 1;
            }
        }
    }

    let mut actual_reads = HashMap::new();
    for op in ops {
        for &(addr, size) in expected_reads.keys() {
            if std::ptr::fn_addr_eq(op.op, local_tee_op(size)) {
                continue;
            }
            let count = op
                .operands
                .iter()
                .filter(|operand| matches!(operand, PackedOperand::LocalAddr(local_addr) if *local_addr == addr))
                .count();
            if count > 0 {
                *actual_reads.entry((addr, size)).or_insert(0usize) += count;
            }
        }
    }

    for (slot_key, expected) in expected_reads {
        if actual_reads.get(&slot_key).copied().unwrap_or_default() < expected {
            return false;
        }
    }

    for (&value, slot) in &spill_plan.slots {
        if !graph[value.0].needs_spill {
            return false;
        }
        let tee_count = ops
            .iter()
            .filter(|op| {
                op.source_start.is_none()
                    && std::ptr::fn_addr_eq(op.op, local_tee_op(slot.size))
                    && matches!(op.operands.first(), Some(PackedOperand::LocalAddr(addr)) if *addr == slot.addr)
            })
            .count();
        if tee_count == 0 {
            return false;
        }
    }

    true
}

fn verify_barrier_op_counts(
    program: &BasicBlockProgram,
    reachable: &[bool],
    mut count_same_op: impl FnMut(usize, Op) -> usize,
) -> bool {
    for block in &program.blocks {
        if !reachable[block.id] {
            continue;
        }
        for record in &program.records[block.start..block.end] {
            if !matches!(effect_barrier(record), EffectBarrier::Call) {
                continue;
            }
            let count = count_same_op(record.old_start, record.op);
            if count != 1 {
                return false;
            }
        }
    }
    true
}

fn count_explicit_ir_ops(bodies: &[BlockBody], source_start: usize, op: Op) -> usize {
    let mut count = 0usize;
    for body in bodies {
        count += body
            .ops
            .iter()
            .filter(|entry| {
                entry.source_start == Some(source_start) && std::ptr::fn_addr_eq(entry.op, op)
            })
            .count();
        count += body
            .terminator
            .iter()
            .filter(|entry| {
                entry.source_start == Some(source_start) && std::ptr::fn_addr_eq(entry.op, op)
            })
            .count();
    }
    count
}

fn decode_const(record: &DecodedInstr) -> Option<(ValType, ConstValue)> {
    if record.op_eq(vm::op_i32_const) {
        return Some((ValType::I32, ConstValue::I32(record.operand_i32(0))));
    }
    if record.op_eq(vm::op_i64_const) {
        return Some((ValType::I64, ConstValue::I64(record.operand_i64(0))));
    }
    if record.op_eq(vm::op_f32_const) {
        return Some((ValType::F32, ConstValue::F32(record.operand_f32(0))));
    }
    if record.op_eq(vm::op_f64_const) {
        return Some((ValType::F64, ConstValue::F64(record.operand_f64(0))));
    }
    None
}

