        || record.op_eq(vm::op_i64_store16_indexed_shared as Op)
        || record.op_eq(vm::op_i64_store32_indexed_shared as Op)
        || record.op_eq(vm::op_i64_store_local as Op)
        || record.op_eq(vm::op_i64_store8_local as Op)
