        let spec = expect_specialized_direct_call_consumer(&graph, &body, 2);
        assert!(std::ptr::fn_addr_eq(spec.call_op, vm::op_return_call as Op));
        assert_eq!(spec.absorbed_ops, BTreeSet::from([0usize]));
